// One row per investor_response in PIPELINE.
// received_at is NOT NULL, and PIPELINE has no reply-date column, so the date
// is taken in this order and the source is recorded so nothing is passed off
// as more precise than it is:
//   1. a date written inside the response text itself
//   2. last_contact
//   3. the latest follow-up or share date
// A row with none of those is skipped rather than given a made-up date.
const vr = $('GET pipeline').first().json.valueRanges[0].values;
const h = vr[0];
const rows = vr.slice(1).map(function (r) { var o = {}; h.forEach(function (k, i) { o[k] = r[i] === undefined ? '' : r[i]; }); return o; });
const nz = function (s) { return String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]/g, ''); };
const sMap = {}; for (const s of ($('GET startup ids').first().json.body || [])) { sMap[nz(s.name)] = s.id; }
const iMap = {}; for (const i of ($('GET investor ids').first().json.body || [])) { iMap[nz(i.name)] = i.id; }
const ISO = /^\d{4}-\d{2}-\d{2}$/;
const MON = { jan:'01',feb:'02',mar:'03',apr:'04',may:'05',jun:'06',jul:'07',aug:'08',sep:'09',oct:'10',nov:'11',dec:'12' };

function dateFromText(t) {
  t = String(t || '');
  let m = /(\d{4})-(\d{2})-(\d{2})/.exec(t);
  if (m) return m[0];
  m = /(\d{1,2})\s*([A-Za-z]{3})[a-z]*\s*(\d{4})?/.exec(t);
  if (m && MON[m[2].toLowerCase()]) {
    const y = m[3] || '2026';
    return y + '-' + MON[m[2].toLowerCase()] + '-' + ('0' + m[1]).slice(-2);
  }
  return null;
}
function kindOf(t) {
  t = String(t || '').toLowerCase();
  if (/bounce|no longer at|undeliver|mailer-daemon/.test(t)) return 'bounce';
  if (/out of office|ooo\b|on leave|vacation/.test(t)) return 'out_of_office';
  if (/pass|not for us|not align|unable to move|not the right fit|will not particip|declin|not interested/.test(t)) return 'pass';
  if (/interest|keen|meeting|call|reviewing|revert|get back|allow us some time|understand more|share the deck|send the deck|mis|intro/.test(t)) return 'interested';
  return 'unclear';
}
const out = []; const src = { in_text: 0, last_contact: 0, send_date: 0 };
let skipped_noid = 0, skipped_nodate = 0, none = 0;
for (const r of rows) {
  const resp = String(r.investor_response || '').trim();
  if (!resp) { none++; continue; }
  const sid = sMap[nz(r.startup)], iid = iMap[nz(r.investor)];
  if (!sid || !iid) { skipped_noid++; continue; }
  let d = dateFromText(resp); let how = 'in_text';
  if (!d) {
    const lc = String(r.last_contact || '').trim();
    if (ISO.test(lc)) { d = lc; how = 'last_contact'; }
  }
  if (!d) {
    const cands = [r.fu3_date, r.fu2_date, r.fu1_date, r.date_shared]
      .map(function (x) { return String(x || '').trim(); }).filter(function (x) { return ISO.test(x); });
    if (cands.length) { d = cands[0]; how = 'send_date'; }
  }
  if (!d || !ISO.test(d)) { skipped_nodate++; continue; }
  src[how] += 1;
  const reason = String(r.pass_reason || '').trim() || null;
  out.push({ investor_id: iid, startup_id: sid, received_at: d + 'T12:00:00+05:30',
             kind: kindOf(resp + ' ' + (reason || '')), reason: reason, raw_snippet: resp.slice(0, 900) });
}
const CH = 400; const chunks = [];
const meta = { total: out.length, src: src, skipped_noid: skipped_noid, skipped_nodate: skipped_nodate,
  kinds: out.reduce(function (a, x) { a[x.kind] = (a[x.kind] || 0) + 1; return a; }, {}) };
for (let i = 0; i < out.length; i += CH) { chunks.push({ json: Object.assign({ rows: out.slice(i, i + CH) }, meta) }); }
return chunks.length ? chunks : [{ json: Object.assign({ rows: [] }, meta) }];

const b = $('Build replies').first().json;
const items = $input.all();
const bad = items.filter(function (i) { return !(i.json.statusCode >= 200 && i.json.statusCode < 300); });
return [{ json: { replies_built: b.total, by_kind: b.kinds, date_source: b.src,
  chunks: items.length, statuses: items.map(function (i) { return i.json.statusCode; }),
  failed: bad.length, errors: bad.map(function (i) { return JSON.stringify(i.json.body).slice(0, 220); }).slice(0, 3),
  skipped_name_not_found: b.skipped_noid, skipped_no_date: b.skipped_nodate } }];
